// 哈希函数（FNV-1a算法）
func hashLine(line []byte) uint64 {
	const prime = 1099511628211
	hash := uint64(14695981039346656037)
	for _, b := range line {
		hash ^= uint64(b)
		hash *= prime
	}
	return hash
}

